/// A building type's data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BuildingData {
    /// The constructor's type argument (normally the slot's own type).
    pub kind: BuildingType,
    /// INI / art name.
    pub ini_name: &'static str,
    /// Exit point for produced units.
    pub exit_point: Coord,
    /// Build level (tech level).
    pub tech_level: u8,
    /// Prerequisite buildings, as a bit mask of `BuildingType` ids.
    pub prerequisites: u64,
    /// `is_scanner` constructor argument.
    pub is_scanner: bool,
    /// `is_regulated` constructor argument.
    pub is_regulated: bool,
    /// `is_bibbed` constructor argument.
    pub is_bibbed: bool,
    /// `is_nominal` constructor argument.
    pub is_nominal: bool,
    /// `is_wall` constructor argument.
    pub is_wall: bool,
    /// `is_factory` constructor argument.
    pub is_factory: bool,
    /// `is_captureable` constructor argument.
    pub is_captureable: bool,
    /// `is_flammable` constructor argument.
    pub is_flammable: bool,
    /// `is_simpledamage` constructor argument.
    pub is_simpledamage: bool,
    /// `is_stealthy` constructor argument.
    pub is_stealthy: bool,
    /// `is_selectable` constructor argument.
    pub is_selectable: bool,
    /// `is_legal_target` constructor argument.
    pub is_legal_target: bool,
    /// `is_insignificant` constructor argument.
    pub is_insignificant: bool,
    /// `is_immune` constructor argument.
    pub is_immune: bool,
    /// `is_theater` constructor argument.
    pub is_theater: bool,
    /// `is_turret_equipped` constructor argument.
    pub is_turret_equipped: bool,
    /// `is_twoshooter` constructor argument.
    pub is_twoshooter: bool,
    /// `is_repairable` constructor argument.
    pub is_repairable: bool,
    /// `is_buildable` constructor argument.
    pub is_buildable: bool,
    /// `is_crew` constructor argument.
    pub is_crew: bool,
    /// `is_sturdy` constructor argument.
    pub is_sturdy: bool,
    /// `tobuild` constructor argument.
    pub builds: Rtti,
    /// `sframe` constructor argument.
    pub start_facing: Dir,
    /// Full strength as written (buildings get double this; see `max_strength`).
    pub strength: u16,
    /// Sight range in cells.
    pub sight_range: i32,
    /// Cost to build, in credits.
    pub cost: i32,
    /// First scenario it's available in.
    pub scenario: i32,
    /// Risk rating.
    pub risk: i32,
    /// Reward rating.
    pub reward: i32,
    /// Houses that may own it, as a bit mask of `House` ids.
    pub owners: u32,
    /// `primary` constructor argument.
    pub primary: Option<Weapon>,
    /// `secondary` constructor argument.
    pub secondary: Option<Weapon>,
    /// `armor` constructor argument.
    pub armor: Armor,
    /// `canenter` constructor argument.
    pub can_enter: i32,
    /// Tiberium storage.
    pub capacity: i32,
    /// Power produced.
    pub power: i32,
    /// Power consumed.
    pub drain: i32,
    /// Footprint.
    pub size: BuildingSize,
    /// Preferred exit cells, as offsets.
    pub exits: &'static [i16],
    /// Occupied cells, as offsets from the top-left.
    pub occupy: &'static [i16],
    /// Overlapped (drawn over) cells, as offsets.
    pub overlap: &'static [i16],
    /// Can't be sold.
    pub is_unsellable: bool,
}

