/// A warhead's data (`WarheadTypeClass`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WarheadData {
    /// Which warhead this is.
    pub kind: Warhead,
    /// Damage spread factor.
    pub spread_factor: i32,
    /// Destroys walls.
    pub wall_destroyer: bool,
    /// Destroys trees.
    pub wood_destroyer: bool,
    /// Destroys Tiberium.
    pub tiberium_destroyer: bool,
    /// Damage against each `Armor`, in 1/256ths.
    pub modifier: [u16; 5],
}

